WITH Src AS (SELECT * FROM order_items WHERE product_id IS NOT NULL OR unit_price >= 340), agg AS (SELECT CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END AS quantity_bucket, COUNT(DISTINCT unit_price) AS unique_products FROM Src GROUP BY CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END) SELECT * FROM agg WHERE unique_products >= 5 ORDER BY quantity_bucket LIMIT 5
